import { buildSignatureBytes } from '@safe-global/protocol-kit'
import { toSafeSignature } from '../safeTransaction'

// Confirmations from throwaway-key Safes 1.5.0 on a Base Sepolia fork; `executed` is what each Safe logged on execution
const TWO_OF_TWO = {
  confirmations: [
    {
      owner: '0xaF9503e481058ACB546d033B0Bb5B9cDf5c709ab',
      signature:
        '0xe5bb15e1131ebbf9a5cf3778e69658734f78ae4c3b7208d068c923eb737c5a142d0df4205133c98f917390e1c4d15872d015cfc79e1c9d85841236d06ae075ea1c',
    }, // EOA
    {
      owner: '0xE9F5f604cbc833A32bBFaf7dDf896fB66f5Af073',
      signature:
        '',
    }, // CONTRACT
  ],
  executed:
    '',
}

const THREE_OF_THREE = {
  confirmations: [
    {
      owner: '0x9ef150E9bDdd63c157E3162B83a565423b2c5a20',
      signature:
        '',
    }, // CONTRACT
    {
      owner: '0xaF9503e481058ACB546d033B0Bb5B9cDf5c709ab',
      signature:
        '0xa31c68b6b3a48786a4882079dacb37e27134d3f117f00af247353899562b1b1c0238502d31a96b0881b9d2852c12ed8ad2f69e2b1aebe0d4919b4b648f403a571b',
    }, // EOA
    {
      owner: '0xE9F5f604cbc833A32bBFaf7dDf896fB66f5Af073',
      signature:
        '',
    }, // CONTRACT
  ],
  executed:
    '',
}

const EOA = TWO_OF_TWO.confirmations[0]
const CONTRACT = TWO_OF_TWO.confirmations[1]

const rebuild = (confirmations: { owner: string; signature: string }[]) =>
  buildSignatureBytes(confirmations.map(({ owner, signature }) => toSafeSignature(owner, signature)))

// The offset word of the static part at `slot` (65 bytes each), in bytes.
const offsetAt = (bytes: string, slot: number) => {
  const start = 2 + 2 * (65 * slot + 32)
  return parseInt(bytes.slice(start, start + 64), 16)
}

describe('toSafeSignature', () => {
  describe('plain signatures stay as they are', () => {
    it('an EOA signature', () => {
      const signature = toSafeSignature(EOA.owner, EOA.signature)

      expect(signature.isContractSignature).toBe(false)
      expect(signature.staticPart()).toBe(EOA.signature)
      expect(signature.dynamicPart()).toBe('')
    })

    it('an eth_sign signature (v = 31/32)', () => {
      const v = parseInt(EOA.signature.slice(-2), 16) + 4
      const ethSign = `${EOA.signature.slice(0, -2)}${v.toString(16)}`
      const signature = toSafeSignature(EOA.owner, ethSign)

      expect(signature.isContractSignature).toBe(false)
      expect(signature.staticPart()).toBe(ethSign)
    })

    it('a pre-approved hash (v = 1)', () => {
      const approved = `0x${EOA.owner.slice(2).toLowerCase().padStart(64, '0')}${'0'.repeat(64)}01`
      const signature = toSafeSignature(EOA.owner, approved)

      expect(signature.isContractSignature).toBe(false)
      expect(signature.staticPart()).toBe(approved)
    })
  })

  describe('contract signatures', () => {
    it('keep only their data', () => {
      const signature = toSafeSignature(CONTRACT.owner, CONTRACT.signature)

      expect(signature.isContractSignature).toBe(true)
      // the 65-byte static part and the 32-byte length word are dropped
      expect(signature.data).toBe(`0x${CONTRACT.signature.slice(2 + 2 * (65 + 32))}`)
    })

    it('lay out an EOA then a contract signature as the Safe executed them', () => {
      const bytes = rebuild(TWO_OF_TWO.confirmations)

      expect(bytes.toLowerCase()).toBe(TWO_OF_TWO.executed.toLowerCase())
      expect(offsetAt(bytes, 1)).toBe(2 * 65)
    })

    it('lay out contract, EOA, contract as the Safe executed them, each pointing past every static part', () => {
      const bytes = rebuild(THREE_OF_THREE.confirmations)
      const firstDataLength = (THREE_OF_THREE.confirmations[0].signature.length - 2) / 2 - 65 - 32

      expect(bytes.toLowerCase()).toBe(THREE_OF_THREE.executed.toLowerCase())
      expect(offsetAt(bytes, 0)).toBe(3 * 65)
      expect(offsetAt(bytes, 2)).toBe(3 * 65 + 32 + firstDataLength)
    })

    it('do not depend on the order the confirmations come in', () => {
      const reversed = [...THREE_OF_THREE.confirmations].reverse()

      expect(rebuild(reversed).toLowerCase()).toBe(THREE_OF_THREE.executed.toLowerCase())
    })
  })

  describe('a v = 0 signature that does not parse stays plain', () => {
    const withOffset = (offset: number) =>
      `${CONTRACT.signature.slice(0, 2 + 64)}${offset.toString(16).padStart(64, '0')}${CONTRACT.signature.slice(2 + 128)}`

    it.each([
      ['an offset inside the static part', withOffset(32)],
      ['an offset past the end', withOffset(10_000)],
      ['data shorter than its length', CONTRACT.signature.slice(0, -64)],
      ['trailing bytes after the data', `${CONTRACT.signature}${'00'.repeat(32)}`],
    ])('%s', (_, malformed) => {
      const signature = toSafeSignature(CONTRACT.owner, malformed)

      expect(signature.isContractSignature).toBe(false)
      expect(signature.staticPart()).toBe(malformed)
    })
  })
})
